+              conversation_completeness |= TCP_COMPLETENESS_FIN;
+          }
+
+          /* RST */
+          if(tcph->th_flags&(TH_RST)) {
+              conversation_completeness |= TCP_COMPLETENESS_RST;
+          }
+      }
+    }
